class CustomerDTO {
  constructor(
    public id: number,
    public name: string,
    public email: string
  ) {}
  getName() { return this.name; }
  setName(n: string) { this.name = n; }
}

class Invoice {
  items: LineItem[] = [];
  total(): number { return this.items.reduce((s,i)=>s + i.price * i.qty, 0); }
  addItem(item: LineItem) { this.items.push(item); }
}

function applyDiscount(inv: Invoice, percent: number) {
  inv.items.forEach(i => i.price *= 1 - percent);
}

// Version A
class MoneyA { constructor(public cents: number, public currency: string) {} }
function addMoneyA(a: MoneyA, b: MoneyA) {
  if (a.currency !== b.currency) throw new Error('currency mismatch');
  return new MoneyA(a.cents + b.cents, a.currency);
}

// Version B
class MoneyB {
  private cents: number;
  private currency: string;
  constructor(cents: number, currency: string) { this.cents = cents; this.currency = currency; }
  add(other: MoneyB) { if (this.currency !== other.currency) throw new Error('currency mismatch'); return new MoneyB(this.cents + other.cents, this.currency); }
}
